import sys
from itertools import combinations, permutations

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))
    k = int(next(iterator))

    grid = []
    for _ in range(n):
        row = []
        for _ in range(m):
            row.append(int(next(iterator)))
        grid.append(row)

    important_coords = []
    for _ in range(k):
        r = int(next(iterator)) - 1
        c = int(next(iterator)) - 1
        important_coords.append((r, c))

    important_set = set(important_coords)

    if k == 1:
        total_cost = grid[important_coords[0][0]][important_coords[0][1]]
        plan = [['.' for _ in range(m)] for _ in range(n)]
        plan[important_coords[0][0]][important_coords[0][1]] = 'X'
        print(total_cost)
        for row in plan:
            print(''.join(row))
        return

    def get_neighbors(r, c):
        neighs = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m:
                neighs.append((nr, nc))
        return neighs

    def bfs_connected(selected_cells, imp_coords):
        if not selected_cells:
            return False

        start = imp_coords[0]
        if start not in selected_cells:
            return False

        visited = set()
        queue = [start]
        visited.add(start)

        while queue:
            curr = queue.pop(0)
            for nr, nc in get_neighbors(curr[0], curr[1]):
                if (nr, nc) in selected_cells and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        for ic in imp_coords:
            if ic not in visited:
                return False
        return True

    def calculate_cost(selected_cells):
        cost = 0
        for r, c in selected_cells:
            cost += grid[r][c]
        return cost

    all_cells = [(r, c) for r in range(n) for c in range(m)]
    total_cells_count = n * m

    best_cost = float('inf')
    best_selection = None

    if total_cells_count <= 20:
        for mask in range(1 << total_cells_count):
            selected = []
            for idx in range(total_cells_count):
                if (mask >> idx) & 1:
                    selected.append(all_cells[idx])

            if len(selected) < k:
                continue

            covers_all = True
            for ic in important_coords:
                if ic not in selected:
                    covers_all = False
                    break
            if not covers_all:
                continue

            if not bfs_connected(set(selected), important_coords):
                continue

            cost = calculate_cost(selected)
            if cost < best_cost:
                best_cost = cost
                best_selection = selected
    else:
        pass

    if best_selection is None:
        return

    plan = [['.' for _ in range(m)] for _ in range(n) ]
    for r, c in best_selection:
        plan[r][c] = 'X'

    print(best_cost)
    for row in plan:
        print(''.join(row))

solve()
